const p = $json.payload ?? $json.body?.payload;   // شغالة سواء جاية بعد OK? أو من الـ Webhook على طول
if (!p) throw new Error('مفيش payload: النود دي لازم تكون بعد «OK?» أو الـ Webhook — راجع التوصيل');
const clinicUrl = 'https://medflow-20261108-011507-qw1nlg7q7-portfolio-site8.vercel.app/';

const lines = [
  `أهلاً بك يا ${p.name} 👋، نود الاطمئنان على صحتك ونتمنى أن تكون بأفضل حال.`,
  ``,
  `نود إعلامك بأنه تم تأكيد *إعادة الحجز (المتابعة)* بنجاح ✅`,
  ``,
  `📌 التخصص: ` + (p.specialty_name || ''),
  `🩺 الطبيب: ` + (p.doctor_name || ''),
  `📅 التاريخ: ` + p.date,
  `⏰ الساعة: ` + (p.time || '')
];

if (p.reason) lines.push(`📝 سبب المتابعة: ` + p.reason);

lines.push(
  `🔢 رقم الحجز: ` + (p.id || ''),
  ``,
  `🌐 يمكنك متابعة تفاصيل حجزك وإدارته عبر الرابط التالي:`,
  `${clinicUrl}`,
  ``,
  `نتمنى لك دوام الصحة والعافية 🌿`
);

return [{ json: { endpoint: 'sendText', body: { number: p.phone_wa, text: lines.join('\n') } } }];

const p = $json.payload ?? $json.body?.payload;   // شغالة سواء جاية بعد OK? أو من الـ Webhook على طول
if (!p) throw new Error('مفيش payload: النود دي لازم تكون بعد «OK?» أو الـ Webhook — راجع التوصيل');
const caption = ['وصفتك الطبية 💊', '', 'المريض: ' + (p.patient_name || ''), 'الطبيب: ' + (p.doctor_name || ''),
  p.specialty_name ? 'التخصص: ' + p.specialty_name : '', p.diagnosis ? 'التشخيص: ' + p.diagnosis : '',
  'رقم الوصفة: ' + (p.code || ''), '', 'نتمنى لك الشفاء العاجل 🌿'].filter((l, i) => l || i === 1 || i === 7).join('\n');
return [{ json: { endpoint: 'sendMedia', body: { number: p.phone_wa, mediatype: 'image', mimetype: p.mimetype || 'image/jpeg',
  caption, media: p.image_base64, fileName: p.filename || 'prescription.jpg' } } }];

const p = $json.payload ?? $json.body?.payload;   
if (!p) throw new Error('مفيش payload: النود دي لازم تكون بعد «OK?» أو الـ Webhook — راجع التوصيل');

const seen = new Set(), out = [];

// تجهيز نص فترة الغياب للتوضيح
const periodText = (p.since && p.until) ? `من تاريخ ${p.since} إلى ${p.until}` : (p.until ? `حتى تاريخ ${p.until}` : '');

for (const m of p.affected || []) {
  if (!m.phone_wa) continue;
  const key = m.phone_wa + '|' + m.date + '|' + m.time;
  if (seen.has(key)) continue; 
  seen.add(key);

  const text = [
    'أهلاً ' + (m.patient_name || '') + ' 👋', '',
    'نعتذر، ' + p.doctor_name + ' غير متاح' + (periodText ? ' (' + periodText + ')' : '') + (p.reason ? ' بسبب: ' + p.reason : '') + '.',
    m.date ? 'موعدك المتأثر: ' + m.date + ' الساعة ' + m.time : '',
    p.cancelled ? 'تم إلغاء موعدك، ويسعدنا نحجزلك موعد بديل.' : 'هنتواصل معاك لتأكيد موعد بديل.',
    '', 'نعتذر عن الإزعاج 🙏'
  ].filter((l, i) => l || i === 1 || i === 5).join('\n');

  out.push({ json: { endpoint: 'sendText', body: { number: m.phone_wa, text } } });
}

// 🛡️ حل احتياطي: لو مصفوفة المرضى فارغة، ابعت رسالة تنبيه للطبيب بالفترة اللي مش هيكون موجود فيها
if (out.length === 0) {
  const fallbackNumber = p.doctor_phone || '201551319329';
  const fallbackText = `⚠️ تنبيه نظام: تم تسجيل عدم توفر للطبيب (${p.doctor_name}) ${periodText ? periodText : ''}. لا توجد مواعيد مرضى متأثرة حالياً.`;
  out.push({ json: { endpoint: 'sendText', body: { number: fallbackNumber, text: fallbackText } } });
}

return out;

// ===================== Build offer msg1 (نسخة مرنة مع تحسين الوسائط) =====================

// 1) قراءة العرض
let offer = null;
try {
  offer = $('OK? offer1').first().json.payload;
} catch (e) {
  offer = null;
}
if (!offer) {
  const first = $input.first()?.json ?? {};
  offer = first.payload ?? first.body?.payload ?? first;
}
if (!offer || (!offer.text && !offer.offer_title && !offer.image_base64)) {
  offer = {
    text: "🔥 *باقة الفحص الشامل* 🔥\n\nتحاليل أساسية + كشف باطنة + تخطيط قلب بسعر موحد.\n\n💰 السعر: *٣٩٩ ر.س* ~٦٥٠ ر.س~\n⏳ ساري حتى خميس 3 ديسمبر 2026\n\n📅 احجز الآن: https://medflow-20261108-011507-evy5fxooz-portfolio-site8.vercel.app/book\n\n— مركز medflow الطبي",
    image_base64: ""
  };
}

const text = String(offer.text || offer.offer_title || '').trim();
let image = typeof offer.image_base64 === 'string' ? offer.image_base64.trim() : '';

// 💡 تحسين جبار: لو الـ base64 أطول من اللازم وضغط السيرفر، يمكنك تحويله إلى نص أو رابط لتجنب خطأ 500
// (لو حابب تبعت رابط مباشر حطه في offer.image_url أو سيبه يبعت النص الإعلاني كاملاً بالرابط)
const hasImage = image.length > 100;

// 2) استخراج الأرقام بمرونة فائقة
const inputs = $input.all();
let phones = [];

for (const item of inputs) {
  const r = item.json || {};

  if (r.wa && (r.wa.to || r.wa.number)) {
    phones.push(r.wa.to || r.wa.number);
    continue;
  }

  const possibleKey = Object.keys(r).find(k => /phone|number|tel|to/i.test(k));
  const val = possibleKey ? r[possibleKey] : (r.patient_phone || r.phone || r.number);
  if (val) phones.push(val);
}

if (phones.length === 0 && Array.isArray(offer.recipients)) {
  phones = offer.recipients.map((r) => (typeof r === 'string' ? r : r.number || r.phone));
}

// 3) تنضيف الأرقام وإزالة التكرار
const seen = new Set();
const out = [];

for (const raw of phones) {
  let phone = String(raw ?? '').trim();
  phone = phone.replace(/^\+/, '').replace(/\D/g, '');

  if (phone.startsWith('00')) phone = phone.slice(2);
  if (/^01\d{9}$/.test(phone)) phone = '2' + phone;

  if (!/^\d{8,15}$/.test(phone) || seen.has(phone)) continue;
  seen.add(phone);

  // 💡 التعديل الإضافي: تجهيز الإرسال (لو الصورة كبيرة وضغطت السيرفر، بيتحول تلقائياً لرسالة نصية قوية تحتوي على كل التفاصيل واللينك عشان تضمن عدم حدوث خطأ 500)
  let messagePayload = {};

  if (hasImage && image.length < 500000) { // لو حجم الصورة مقبول
    messagePayload = {
      to: phone,
      type: 'image',
      caption: text,
      media: image,
      mimetype: offer.mimetype || 'image/jpeg',
      fileName: offer.filename || 'offer.jpg',
    };
  } else {
    // لو الصورة كبيرة جداً أو مفريشة، بنبعت النص الإعلاني (اللي فيه لينك حجز الـ Vercel) مباشرة وبكل قوة
    messagePayload = {
      to: phone,
      type: 'text',
      text: text
    };
  }

  out.push({
    json: {
      wa: messagePayload
    },
  });
}

if (out.length === 0) {
  return [{ json: { skip: true, info: 'NO_VALID_RECIPIENTS', totalReceived: inputs.length, sample: inputs[0] || null } }];
}

return out;

const p = $json.payload ?? $json.body?.payload;   // شغالة سواء جاية بعد OK? أو من الـ Webhook على طول
if (!p) throw new Error('مفيش payload: النود دي لازم تكون بعد «OK?» أو الـ Webhook — راجع التوصيل');
const summary = String(p.summary || '').slice(0, 900);
return [{ json: { endpoint: 'sendMedia', body: { number: p.manager_phone_wa, mediatype: 'document', mimetype: 'application/pdf',
  caption: 'تقرير ' + (p.center_name || '') + (p.period ? ' — ' + p.period : '') + '\n\n' + summary,
  media: p.pdf_base64, fileName: p.filename || 'report.pdf' } } }];

const p = $json.payload ?? $json.body?.payload;   // شغالة سواء جاية بعد OK? أو من الـ Webhook على طول
if (!p) throw new Error('مفيش payload: النود دي لازم تكون بعد «OK?» أو الـ Webhook — راجع التوصيل');
if (Number(p.rating) > 2) return [];   // التنبيه للتقييم المنخفض بس (<=2)
const text = ['⚠️ تقييم منخفض ' + p.rating + '/5', 'المريض: ' + (p.patient_name || ''), p.doctor_name ? 'الطبيب: ' + p.doctor_name : '', p.comment ? 'التعليق: ' + p.comment : '']
  .filter(Boolean).join('\n');
// غيّر رقم المدير هنا
return [{ json: { endpoint: 'sendText', body: { number: '201000000000', text } } }];

// السيرفر (/api/n8n) هو اللي بيبعت بالـ secret. هنا تحقق الحقول بس.
const b = $json.body ?? {};
const p = b.payload && typeof b.payload === 'object' ? b.payload : null;
if (!p) return { json: { ok: false, error: 'BAD_REQUEST' } };
const wa = (v) => /^\d{8,15}$/.test(String(v ?? ''));
const isDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v ?? ''));
if (!['appointment.created','appointment.cancelled','appointment.reminder'].includes(b.event)) return { json: { ok: false, error: 'BAD_EVENT' } };
if (!wa(p.phone_wa)) return { json: { ok: false, error: 'INVALID_PHONE' } };
if (String(p.name ?? '').trim().length < 2 || !isDate(p.date)) return { json: { ok: false, error: 'BAD_FIELDS' } };
return { json: { ok: true, event: b.event, payload: p } };

// السيرفر (/api/n8n) هو اللي بيبعت بالـ secret. هنا تحقق الحقول بس.
