// السيرفر (/api/n8n) هو اللي بيبعت بالـ secret. هنا تحقق الحقول بس.
const b = $json.body ?? {};
const p = b.payload && typeof b.payload === 'object' ? b.payload : null;
if (!p) return { json: { ok: false, error: 'BAD_REQUEST' } };
const wa = (v) => /^\d{8,15}$/.test(String(v ?? ''));
const isDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v ?? ''));
if (!wa(p.phone_wa)) return { json: { ok: false, error: 'INVALID_PHONE' } };
if (!p.image_base64 || String(p.image_base64).length > 8000000) return { json: { ok: false, error: 'BAD_FILE' } };
return { json: { ok: true, event: b.event, payload: p } };

// السيرفر (/api/n8n) هو اللي بيبعت بالـ secret. هنا تحقق الحقول بس.
const b = $json.body ?? {};
const p = b.payload && typeof b.payload === 'object' ? b.payload : null;
if (!p) return { json: { ok: false, error: 'BAD_REQUEST' } };
const wa = (v) => /^\d{8,15}$/.test(String(v ?? ''));
const isDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v ?? ''));
const r = Number(p.rating);
if (!Number.isInteger(r) || r < 1 || r > 5) return { json: { ok: false, error: 'BAD_RATING' } };
return { json: { ok: true, event: b.event, payload: p } };

// السيرفر (/api/n8n) هو اللي بيبعت بالـ secret. هنا تحقق الحقول بس.
const b = $json.body ?? {};
const p = b.payload && typeof b.payload === 'object' ? b.payload : null;
if (!p) return { json: { ok: false, error: 'BAD_REQUEST' } };
const wa = (v) => /^\d{8,15}$/.test(String(v ?? ''));
const isDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v ?? ''));
if (!wa(p.manager_phone_wa)) return { json: { ok: false, error: 'INVALID_PHONE' } };
if (!p.pdf_base64 || String(p.pdf_base64).length > 8000000) return { json: { ok: false, error: 'BAD_FILE' } };
return { json: { ok: true, event: b.event, payload: p } };

const b = $json.body ?? {};
const p = b.payload && typeof b.payload === 'object' ? b.payload : null;
if (!p) return { json: { ok: false, error: 'BAD_REQUEST' } };

// السماح بوجود علامة + اختيارية في البداية
const wa = (v) => /^\+?\d{8,15}$/.test(String(v ?? '').trim());

// استخراج المستلمين إن وجدوا، أو دعم رقم منفرد، أو تمرير الطلب طالما الحقول الأساسية موجودة
let recipients = [];
if (Array.isArray(p.recipients) && p.recipients.length > 0) {
  recipients = p.recipients;
} else if (p.number) {
  recipients = [{ number: p.number }];
}

// التحقق من صحة الأرقام فقط في حال وجود مستلمين، أو تجاوزها إذا لم تكن مطلوبة في هذا الـ endpoint
if (recipients.length > 0) {
  for (const recipient of recipients) {
    if (!wa(recipient.number)) {
      return { json: { ok: false, error: 'INVALID_PHONE', invalid_number: recipient.number } };
    }
  }
}

// التحقق من وجود محتوى للرسالة
if (!p.text && !p.image_base64 && !p.offer_title) {
  return { json: { ok: false, error: 'EMPTY_OFFER' } };
}

return { json: { ok: true, event: b.event, payload: p } };

// السيرفر (/api/n8n) هو اللي بيبعت بالـ secret. هنا تحقق الحقول بس.
const b = $json.body ?? {};
const p = b.payload && typeof b.payload === 'object' ? b.payload : null;
if (!p) return { json: { ok: false, error: 'BAD_REQUEST' } };
const wa = (v) => /^\d{8,15}$/.test(String(v ?? ''));
const isDate = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v ?? ''));
if (!String(p.doctor_name ?? '').trim()) return { json: { ok: false, error: 'BAD_FIELDS' } };
if (!Array.isArray(p.affected) || p.affected.length > 200) return { json: { ok: false, error: 'BAD_FIELDS' } };
return { json: { ok: true, event: b.event, payload: p } };

// تنبيه التعليقات السلبية — الموقع بيبعت هنا بس لما تحليل المشاعر يقول «سلبي».
const b = $json.body ?? {};
const p = b.payload && typeof b.payload === 'object' ? b.payload : null;
if (!p) return { json: { ok: false, error: 'BAD_REQUEST' } };
if (b.event !== 'review.negative') return { json: { ok: false, error: 'WRONG_EVENT' } };
const r = Number(p.rating);
if (!Number.isInteger(r) || r < 1 || r > 5) return { json: { ok: false, error: 'BAD_RATING' } };
if (p.sentiment !== 'negative') return { json: { ok: false, error: 'NOT_NEGATIVE' } };
return { json: { ok: true, event: b.event, payload: p } };

// ===================== Evolution API — تجهيز الإرسال (مكان واحد لكل الفروع) =====================
// كل Build node بيطلع:  { wa: { to, type, text, caption, media, mimetype, fileName } }
//   type = 'text' | 'image' | 'video' | 'document' | 'audio' (فويس نوت) | 'file' (يحدد النوع من mimetype)
//   media = base64 (مع أو من غير data:...;base64,) أو رابط https
// وبيقبل كمان الشكل القديم { endpoint, body } زي ما هو.
// ⬇️ غيّر الـ 3 قيم دول بس
const HOST = 'http://host.docker.internal:8080';   // Evolution على نفس الجهاز (n8n جوه Docker)
const INSTANCE = 'whatsapp_agent';
const VERSION = 'v2';                          // Evolution v2.x = 'v2' ، v1.x = 'v1'

const EXT = {
  'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/gif': 'gif',
  'video/mp4': 'mp4', 'video/3gpp': '3gp', 'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a',
  'audio/webm': 'webm', 'audio/wav': 'wav', 'application/pdf': 'pdf', 'text/plain': 'txt',
  'application/msword': 'doc', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/vnd.ms-excel': 'xls', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  'application/zip': 'zip',
};
const MIME_BY_EXT = Object.fromEntries(Object.entries(EXT).map(([m, e]) => [e, m]));

const base = HOST.replace(/\/+$/, '');
const url = (endpoint) => `${base}/message/${endpoint}/${encodeURIComponent(INSTANCE)}`;

function cleanNumber(v) {
  const s = String(v ?? '').trim();
  if (/@(g\.us|s\.whatsapp\.net|lid)$/.test(s)) return s;           // جروب أو JID جاهز
  const d = s.replace(/\D/g, '');
  return /^\d{8,15}$/.test(d) ? d : '';
}

function splitMedia(media, mimetype) {
  let m = String(media ?? '').trim();
  let mime = mimetype ? String(mimetype).toLowerCase() : '';
  if (!m) return { media: '', mime };
  if (/^https?:\/\//i.test(m)) {
    if (!mime) mime = MIME_BY_EXT[(m.split('?')[0].split('.').pop() || '').toLowerCase()] || '';
    return { media: m, mime, isUrl: true };
  }
  const dataUri = /^data:([^;,]+)?(;[^,]*)?,/i.exec(m);
  if (dataUri) { if (!mime && dataUri[1]) mime = dataUri[1].toLowerCase(); m = m.slice(dataUri[0].length); }
  m = m.replace(/\s+/g, '');                                          // base64 خام من غير مسافات/سطور
  return { media: m, mime };
}

function kindOf(type, mime) {
  const t = String(type || '').toLowerCase();
  if (['text', 'image', 'video', 'document', 'audio'].includes(t)) return t;
  if (t === 'voice' || t === 'ptt') return 'audio';
  if (mime.startsWith('image/')) return 'image';
  if (mime.startsWith('video/')) return 'video';
  if (mime.startsWith('audio/')) return 'audio';
  return 'document';
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  // الشكل القديم: { endpoint, body } -> يعدّي زي ما هو (بعد تنضيف الرقم والميديا)
  if (j.endpoint && j.body && !j.wa) {
    const body = { ...j.body, number: cleanNumber(j.body.number) || j.body.number };
    if (body.media) { const s = splitMedia(body.media, body.mimetype); body.media = s.media; if (s.mime) body.mimetype = s.mime; }
    if (body.audio) body.audio = splitMedia(body.audio).media;
    out.push({ json: { url: url(j.endpoint), endpoint: j.endpoint, body } });
    continue;
  }
  const wa = j.wa;
  if (!wa) continue;
  const number = cleanNumber(wa.to ?? wa.number);
  if (!number) { out.push({ json: { skip: true, error: 'BAD_NUMBER', to: wa.to ?? wa.number } }); continue; }

  const s = splitMedia(wa.media, wa.mimetype);
  const kind = s.media ? kindOf(wa.type, s.mime) : 'text';
  const text = String(wa.text ?? '').trim();
  const caption = String(wa.caption ?? text).slice(0, 1024);

  if (kind === 'text') {
    if (!text) { out.push({ json: { skip: true, error: 'EMPTY_TEXT', to: number } }); continue; }
    out.push({ json: { url: url('sendText'), endpoint: 'sendText',
      body: VERSION === 'v1' ? { number, textMessage: { text } } : { number, text } } });
    continue;
  }

  if (kind === 'audio') {
    // فويس نوت (PTT) — Evolution بيحوّله لـ opus لوحده
    out.push({ json: { url: url('sendWhatsAppAudio'), endpoint: 'sendWhatsAppAudio',
      body: VERSION === 'v1' ? { number, audioMessage: { audio: s.media } } : { number, audio: s.media } } });
    // الفويس مالوش caption: لو فيه نص يتبعت رسالة لوحده بعده
    if (wa.caption || wa.text) out.push({ json: { url: url('sendText'), endpoint: 'sendText',
      body: VERSION === 'v1' ? { number, textMessage: { text: caption } } : { number, text: caption } } });
    continue;
  }

  const mime = s.mime || (kind === 'image' ? 'image/jpeg' : kind === 'video' ? 'video/mp4' : 'application/octet-stream');
  let fileName = String(wa.fileName || wa.file_name || '').trim();
  if (!fileName && s.isUrl) fileName = decodeURIComponent(s.media.split('?')[0].split('/').pop() || '');
  if (!fileName) fileName = `${kind === 'document' ? 'file' : kind}.${EXT[mime] || 'bin'}`;
  else if (!/\.[a-z0-9]{2,5}$/i.test(fileName) && EXT[mime]) fileName += `.${EXT[mime]}`;

  const body = VERSION === 'v1'
    ? { number, mediaMessage: { mediatype: kind, fileName, caption, media: s.media } }
    : { number, mediatype: kind, mimetype: mime, caption, media: s.media, fileName };
  out.push({ json: { url: url('sendMedia'), endpoint: 'sendMedia', body } });
}
return out.filter((x) => !x.json.skip);   // الرقم الغلط أو الرسالة الفاضية بتتخطى بدل ما توقع الـ workflow

// ===================== Evolution API — تجهيز الإرسال (مكان واحد لكل الفروع) =====================
