  if (key.fromMe || !jid || jid.endsWith('@g.us') || jid === 'status@broadcast' || jid.endsWith('@newsletter')) return [];

  let msg = d.message ?? {};
  for (let i = 0; i < 3; i++) {
    const w = WRAPPERS.find(k => msg[k]?.message);
    if (!w) break;
    msg = msg[w].message;
  }
  const kind  = Object.keys(msg).find(k => !['messageContextInfo', 'senderKeyDistributionMessage'].includes(k)) ?? d.messageType ?? '';
  const type  = TYPE_MAP[kind] ?? 'unsupported';
  const inner = msg[kind] ?? {};

  const altJid = [key.remoteJidAlt, key.senderPn, d.senderPn].find(isPhone);
  const phone  = isPhone(jid) ? digits(jid) : (altJid ? digits(altJid) : null);
  const user_id = isLid(jid) ? jid : null;

  const media = MEDIA.includes(type) ? inner : null;
  const loc   = type === 'location' ? inner : null;
  const text  = kind === 'conversation' ? msg.conversation : (kind === 'extendedTextMessage' ? inner.text : null);
  const content = type === 'text' ? (text ?? null) : (media?.caption ?? null);

  let payload = null;
  if (loc) payload = { latitude: loc.degreesLatitude, longitude: loc.degreesLongitude, name: loc.name ?? null, address: loc.address ?? null, maps_link: `https://www.google.com/maps?q=${loc.degreesLatitude},${loc.degreesLongitude}` };
  if (type === 'reaction') payload = { emoji: inner.text ?? null, reacted_to: inner.key?.id ?? null };
  if (type === 'contacts') payload = { contacts: inner.contacts ?? [inner] };
  if (type === 'audio')    payload = { voice: inner.ptt ?? null };

  const ts = typeof d.messageTimestamp === 'object' ? d.messageTimestamp?.low : d.messageTimestamp;

  return [{ json: {
    instance: body.instance,
    remote_jid: jid,
    phone, user_id,
    reply_to: phone ?? jid,
    username: null,
    name: d.pushName ?? '',
    message_id: key.id,
    timestamp: Number(ts) || Math.floor(Date.now() / 1000),
    type,
    content,
    caption: media?.caption ?? null,
    button_reply: msg.buttonsResponseMessage?.selectedButtonId ?? msg.templateButtonReplyMessage?.selectedId ?? msg.listResponseMessage?.singleSelectReply?.selectedRowId ?? null,
    button_title: msg.buttonsResponseMessage?.selectedDisplayText ?? msg.templateButtonReplyMessage?.selectedDisplayText ?? msg.listResponseMessage?.title ?? null,
    reply_to_message_id: inner.contextInfo?.stanzaId ?? null,
    media_id: media ? key.id : null,
    media_mime_type: media?.mimetype ?? null,
    media_filename: media?.fileName ?? null,
    media_sha256: typeof media?.fileSha256 === 'string' ? media.fileSha256 : null,
    payload,
  } }];
});

const body = $('Webhook').first().json.body ?? {};
