// دالة لتنظيف وتنسيق رقم الهاتف وإضافة كود الدولة تلقائياً
function formatPhoneNumber(phone, defaultCountryCode = '20') {
  if (!phone) return '';

  // 1. تحويل القيمة إلى نص وإزالة أي مسافات أو رموز خاصة (ما عدا علامة +)
  let cleaned = String(phone).trim().replace(/[^\d+]/g, '');

  // 2. إذا كان الرقم يبدأ بعلامة +، نقوم فقط بإزالة الزوائد والاحتفاظ بالأرقام
  if (cleaned.startsWith('+')) {
    cleaned = cleaned.replace('+', '');
  }

  // 3. إذا كان الرقم محلياً ويبدأ بـ 0 (مثل 01012345678 في مصر أو 0501234567 في السعودية)
  if (cleaned.startsWith('0')) {
    cleaned = defaultCountryCode + cleaned.substring(1);
  } 
  // 4. إذا لم يكن يحتوي على مفتاح الدولة نهائياً (مثلاً مكون من 9 أو 10 أرقام ولا يبدأ بـ 0)
  else if (cleaned.length === 10 || cleaned.length === 9) {
    cleaned = defaultCountryCode + cleaned;
  }

  return cleaned;
}

